using System;

class Program
{
    static void Main()
    {
        // 1. Declaration only (gets default value)
        int score;
        Console.WriteLine(score); // Compile error: use of unassigned variable

        // 2. Declaration with initialization
        int lives = 3;
        string playerName = "Alice";
        bool isGameOver = false;

        // 3. Declare multiple variables of the same type
        int x = 10, y = 20, z = 30;

        // 4. Change value after declaration
        lives = 2;
        Console.WriteLine($"{playerName} has {lives} lives left");
    }
}

using System;

class Program
{
    static void Main()
    {
        // Type is inferred from the initializer
        var age = 25;           // int
        var price = 19.99;      // double
        var name = "Bob";      // string
        var isActive = true;    // bool
        var items = new[] { 1, 2, 3 }; // int[]

        // Print inferred types
        Console.WriteLine(age.GetType());    // System.Int32
        Console.WriteLine(price.GetType());  // System.Double
        Console.WriteLine(name.GetType());   // System.String

        // This would NOT compile — type is locked
        // var score;
        // score = 10;

        // var requires initialization on the same line
    }
}

using System;

class Config
{
    // const — compile-time constant, must be assigned here
    public const int MaxConnections = 100;
    public const string AppName = "Quotient";

    // readonly — runtime constant, can be assigned in constructor
    public readonly Guid InstanceId;
    public readonly DateTime StartTime;

    public Config()
    {
        // Can assign readonly fields in the constructor
        InstanceId = Guid.NewGuid();
        StartTime = DateTime.UtcNow;
    }

    public void PrintConfig()
    {
        Console.WriteLine($"{AppName}: max {MaxConnections} connections");
        Console.WriteLine($"Instance: {InstanceId}");
    }
}

class Program
{
    static void Main()
    {
        var config = new Config();
        config.PrintConfig();

        // const is replaced at compile time — no memory overhead
        int limit = Config.MaxConnections;
    }
}
